#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}
# ──────────────────────────────────────────────────────────────────────────
# STAGES: lomi.sairam.cc production deploy setup.
# Values land in .env.deploy (gitignored, never commit it) and in GitHub
# Actions secrets consumed by .github/workflows/deploy.yml.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=10
ENV_FILE=".env.deploy"
KEY_FILE="$HOME/.ssh/lomi_deploy"
DOMAIN="lomi.sairam.cc"

banner "Lomi: deploy setup for $DOMAIN"

# ── 1. Prerequisites ──────────────────────────────────────────────────────
stage "Prerequisites"
say "Checking the tools this wizard needs on your machine."
missing=0
for tool in ssh ssh-keygen openssl gh; do
  if command -v "$tool" >/dev/null 2>&1; then say "ok   $tool"; else warn "missing $tool"; missing=1; fi
done
if command -v gh >/dev/null 2>&1 && ! gh auth status >/dev/null 2>&1; then
  warn "gh is not logged in: run 'gh auth login', then re-run this wizard"
  missing=1
fi
if (( missing )); then
  warn "Install or fix the items above, then re-run."
  exit 1
fi
note "GHCR packages default to private. That is fine: the deploy job runs 'docker login ghcr.io' on the VPS itself."
pause

# ── 2. VPS address ────────────────────────────────────────────────────────
stage "VPS address"
say "The VPS you will deploy to (needs your own SSH access already)."
note "Saved only to $ENV_FILE, which is gitignored. Never commit it."
ask VPS_TARGET "VPS as user@ip (for example root@203.0.113.10):"
[[ "$VPS_TARGET" == *@* ]] || { warn "expected user@ip"; exit 1; }
write_env VPS_TARGET "$VPS_TARGET"
VPS_USER_PART="${VPS_TARGET%@*}"
VPS_HOST_PART="${VPS_TARGET#*@}"

# ── 3. Deploy key ─────────────────────────────────────────────────────────
stage "Dedicated deploy key"
say "GitHub Actions gets its own key, separate from your personal one."
if [[ -f "$KEY_FILE" ]]; then
  say "Found existing $KEY_FILE, reusing it."
else
  mkdir -p "$HOME/.ssh"
  ssh-keygen -t ed25519 -f "$KEY_FILE" -N "" -C "lomi-deploy"
fi
[[ -f "$KEY_FILE.pub" ]] || ssh-keygen -y -f "$KEY_FILE" > "$KEY_FILE.pub"

# ── 4. Install the public key on the VPS ──────────────────────────────────
stage "Authorize the key on the VPS"
say "This appends $KEY_FILE.pub to ~/.ssh/authorized_keys on $VPS_TARGET."
say "You authenticate with your own existing key or password."
if confirm "Install the deploy public key on $VPS_TARGET?"; then
  if command -v ssh-copy-id >/dev/null 2>&1; then
    ssh-copy-id -o StrictHostKeyChecking=accept-new -i "$KEY_FILE.pub" "$VPS_TARGET"
  else
    ssh -o StrictHostKeyChecking=accept-new "$VPS_TARGET" 'umask 077; mkdir -p ~/.ssh && cat >> ~/.ssh/authorized_keys' < "$KEY_FILE.pub"
  fi
  say "Testing the dedicated key..."
  ssh -i "$KEY_FILE" -o IdentitiesOnly=yes -o StrictHostKeyChecking=accept-new "$VPS_TARGET" 'echo key login ok' \
    || { warn "the deploy key could not log in; fix this before continuing"; exit 1; }
else
  warn "Skipped. The deploy job cannot connect until this key is authorized."
  SKIPPED+=("install $KEY_FILE.pub in authorized_keys on $VPS_TARGET")
fi

# ── 5. Docker on the VPS ──────────────────────────────────────────────────
stage "Docker on the VPS"
if ssh -i "$KEY_FILE" -o IdentitiesOnly=yes -o StrictHostKeyChecking=accept-new "$VPS_TARGET" 'docker compose version' 2>/dev/null; then
  say "Docker and the compose plugin are already installed."
else
  warn "Docker with the compose plugin was not found on $VPS_TARGET."
  say "Official convenience script (https://docs.docker.com/engine/install/ubuntu/#install-using-the-convenience-script):"
  say "  curl -fsSL https://get.docker.com | sh"
  if [[ "$VPS_USER_PART" != "root" ]]; then
    say "  sudo usermod -aG docker $VPS_USER_PART   (so the deploy user can run docker)"
  fi
  if confirm "Run that on $VPS_TARGET now?"; then
    if [[ "$VPS_USER_PART" == "root" ]]; then
      ssh -i "$KEY_FILE" -o IdentitiesOnly=yes -o StrictHostKeyChecking=accept-new "$VPS_TARGET" 'curl -fsSL https://get.docker.com | sh'
    else
      ssh -t -i "$KEY_FILE" -o IdentitiesOnly=yes -o StrictHostKeyChecking=accept-new "$VPS_TARGET" 'curl -fsSL https://get.docker.com | sudo sh && sudo usermod -aG docker "$USER"'
    fi
    ssh -i "$KEY_FILE" -o IdentitiesOnly=yes -o StrictHostKeyChecking=accept-new "$VPS_TARGET" 'docker compose version' \
      || { warn "docker compose still not usable; check the VPS by hand"; exit 1; }
  else
    SKIPPED+=("install Docker + compose plugin on $VPS_TARGET")
  fi
fi

# ── 6. DNS ────────────────────────────────────────────────────────────────
stage "DNS A record"
say "At your DNS provider for sairam.cc, create this record:"
step "Type A   Name: lomi   Value: $VPS_HOST_PART   (lowest/automatic TTL)"
note "Caddy requests the TLS certificate on first start, so the record must resolve first. Ports 80 and 443 must be open on the VPS firewall."
resolve_domain() {
  if command -v dig >/dev/null 2>&1; then dig +short "$DOMAIN" A
  elif command -v nslookup >/dev/null 2>&1; then nslookup "$DOMAIN" 2>/dev/null | awk '/^Address/ {print $NF}' | tail -n +2
  else getent hosts "$DOMAIN" 2>/dev/null | awk '{print $1}'; fi
}
while true; do
  pause "Press Enter once the record is created, to check it."
  if resolve_domain | grep -qxF "$VPS_HOST_PART"; then
    say "$DOMAIN resolves to $VPS_HOST_PART."
    break
  fi
  warn "$DOMAIN does not resolve to $VPS_HOST_PART yet (DNS can take a few minutes)."
  confirm "Check again?" || { SKIPPED+=("DNS A record lomi -> $VPS_HOST_PART"); break; }
done

# ── 7. Generate secrets ───────────────────────────────────────────────────
stage "Generate secrets"
say "Creating random secrets locally. They are never printed."
note "Kept in $ENV_FILE so a re-run reuses them. Rotating KEY_ENCRYPTION_KEY would make stored LLM keys unreadable."
existing=$(_existing SESSION_SECRET || true)
if [[ -n "$existing" ]]; then SESSION_SECRET="$existing"; else write_env SESSION_SECRET "$(openssl rand -hex 32)"; fi
existing=$(_existing KEY_ENCRYPTION_KEY || true)
if [[ -n "$existing" ]]; then KEY_ENCRYPTION_KEY="$existing"; else write_env KEY_ENCRYPTION_KEY "$(openssl rand -hex 32)"; fi
existing=$(_existing POSTGRES_PASSWORD || true)
if [[ -n "$existing" ]]; then POSTGRES_PASSWORD="$existing"; else write_env POSTGRES_PASSWORD "$(openssl rand -hex 24)"; fi
say "SESSION_SECRET, KEY_ENCRYPTION_KEY and POSTGRES_PASSWORD are ready."

# ── 8. GitHub secrets ─────────────────────────────────────────────────────
stage "GitHub Actions secrets"
say "Setting the six required secrets on this repo (gh secret set)."
if confirm "Set VPS_HOST, VPS_USER, VPS_SSH_KEY, SESSION_SECRET, KEY_ENCRYPTION_KEY, POSTGRES_PASSWORD?"; then
  set_secret VPS_HOST "$VPS_HOST_PART"
  set_secret VPS_USER "$VPS_USER_PART"
  set_secret VPS_SSH_KEY "$(cat "$KEY_FILE")"
  set_secret SESSION_SECRET "$SESSION_SECRET"
  set_secret KEY_ENCRYPTION_KEY "$KEY_ENCRYPTION_KEY"
  set_secret POSTGRES_PASSWORD "$POSTGRES_PASSWORD"
else
  SKIPPED+=("gh secret set VPS_HOST VPS_USER VPS_SSH_KEY SESSION_SECRET KEY_ENCRYPTION_KEY POSTGRES_PASSWORD")
fi

# ── 9. Optional S3 storage ────────────────────────────────────────────────
stage "Optional: S3-compatible storage"
say "Without S3 the VPS stores uploads in the 'files' Docker volume. That works; S3 is optional."
if confirm "Use S3-compatible storage?"; then
  say "Open your provider's dashboard, create a bucket and an access key, then paste the values."
  S3_URL=""
  ask S3_URL "Provider dashboard URL to open (blank to skip opening):" || true
  [[ -n "$S3_URL" ]] && open_url "$S3_URL"
  ask S3_ENDPOINT "S3 endpoint URL:"
  ask S3_REGION "Region:"
  ask S3_BUCKET "Bucket name (must already exist):"
  ask S3_ACCESS_KEY_ID "Access key ID:"
  ask_secret S3_SECRET_ACCESS_KEY "Secret access key:"
  S3_FORCE_PATH_STYLE=""
  ask S3_FORCE_PATH_STYLE "Force path style (true/false, blank for provider default):" || true
  for k in S3_ENDPOINT S3_REGION S3_BUCKET S3_ACCESS_KEY_ID; do write_env "$k" "${!k}"; done
  for k in S3_ENDPOINT S3_REGION S3_BUCKET S3_ACCESS_KEY_ID S3_SECRET_ACCESS_KEY; do set_secret "$k" "${!k}"; done
  [[ -n "$S3_FORCE_PATH_STYLE" ]] && set_secret S3_FORCE_PATH_STYLE "$S3_FORCE_PATH_STYLE"
else
  say "Skipping S3."
fi

# ── 10. Summary ───────────────────────────────────────────────────────────
stage "Done"
say "Everything the deploy workflow needs is configured."
step "Next: merge to main. After CI passes, the Deploy workflow builds the images and ships them to $VPS_TARGET."
step "Then check https://$DOMAIN/api/health"
note "Never commit $ENV_FILE or $KEY_FILE."
pause

finish
}

run_wizard "$@"; exit
